// Parse Claude's response into draft messages + notes (R3: full messages[])
const response = $input.item.json;
let raw = "";
try {
  raw = response.content[0].text;
} catch (e) {
  return { json: {
    messages: ["(empty Claude response — check API node)"],
    messages_count: 1,
    notes: "ERROR: could not extract text from Claude API response",
    parse_status: "extract_failed",
    raw_response: JSON.stringify(response),
    customer_phone: $('Build Prompt').item.json.customerPhone,
    customer_name: $('Build Prompt').item.json.customerName,
    user_message: $('Build Prompt').item.json.userMessage,
    memory_context: $('Build Prompt').item.json.memoryContext
  } };
}
let cleaned = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/i, '').trim();
let parsed;
let parseStatus = "ok";
try {
  parsed = JSON.parse(cleaned);
  if (!Array.isArray(parsed.messages) || parsed.messages.length === 0) {
    throw new Error("messages array missing or empty");
  }
} catch (e) {
  parsed = { messages: [raw], notes_for_zayn: "(JSON parse failed — Claude returned plain text. Error: " + e.message + ")" };
  parseStatus = "fallback_plain_text";
}
const messages = parsed.messages.slice(0, 4).map(m => String(m));
return { json: {
  messages: messages,
  messages_count: messages.length,
  notes: parsed.notes_for_zayn || "(no notes)",
  parse_status: parseStatus,
  raw_response: raw,
  customer_phone: $('Build Prompt').item.json.customerPhone,
  customer_name: $('Build Prompt').item.json.customerName,
  user_message: $('Build Prompt').item.json.userMessage,
  memory_context: $('Build Prompt').item.json.memoryContext
} };

// Queue pending draft + format Telegram message (R3: numbered multi-message preview)
const input = $input.item.json;
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.pendingQueue)) data.pendingQueue = [];

const id = $now.toMillis().toString() + '_' + Math.random().toString(36).slice(2, 7);
const messages = (Array.isArray(input.messages) && input.messages.length)
  ? input.messages.map(m => String(m))
  : ['(empty draft)'];

const pending = {
  id: id,
  timestamp: $now.toISO(),
  customer_phone: input.customer_phone,
  customer_name: input.customer_name || '',
  customer_message: input.user_message,
  memory_context: input.memory_context,
  messages: messages,
  draft_text: messages.join('\n\n'),
  messages_sent_count: 0,
  notes: input.notes,
  telegram_message_id: null,
  telegram_chat_id: 5532831477,
  status: 'pending'
};
data.pendingQueue.push(pending);

const preview = messages.length === 1
  ? messages[0]
  : messages.map((m, i) => (i + 1) + '. ' + m).join('\n');
const header = messages.length === 1 ? '💬 DRAFT:' : ('💬 DRAFT (' + messages.length + ' messages):');

const text = [
  '📩 NEW from ' + pending.customer_phone,
  'Name: ' + (pending.customer_name || '(unknown)'),
  '',
  'They said:',
  '"' + pending.customer_message + '"',
  '',
  '---',
  header,
  preview,
  '',
  '📝 Notes: ' + pending.notes
].join('\n');

const reply_markup = {
  inline_keyboard: [
    [{ text: '✅ Send', callback_data: 'send:' + id }, { text: '✏️ Edit', callback_data: 'edit:' + id }],
    [{ text: '🔁 Regen', callback_data: 'regen:' + id }, { text: '❌ Skip', callback_data: 'skip:' + id }]
  ]
};

return { json: { telegram_payload: { chat_id: 5532831477, text: text, reply_markup: reply_markup }, draft_id: id } };

// Save Telegram message_id back to the pending draft for later editing
const tgResponse = $input.item.json;
const messageId = tgResponse.result?.message_id;
const draftId = $('Queue & Format').item.json.draft_id;

const data = $getWorkflowStaticData('global');
const entry = (data.pendingQueue || []).find(d => d.id === draftId);
if (entry && messageId) {
  entry.telegram_message_id = messageId;
}
return { json: { draft_id: draftId, telegram_message_id: messageId, ok: tgResponse.ok } };

// Verify the update is from Zayn (admin)
const body = $input.item.json.body || {};
const adminId = 5532831477;

const fromId = body.callback_query?.from?.id || body.message?.from?.id;

if (fromId !== adminId) {
  // Silently drop — return empty
  return null;
}

// Tag the update type for downstream routing
let updateType = 'unknown';
if (body.callback_query) updateType = 'callback_query';
else if (body.message?.text) updateType = 'message';

return {
  json: {
    update_type: updateType,
    callback_query: body.callback_query || null,
    message: body.message || null,
    raw: body
  }
};

// Parse callback_data and look up the draft
const cq = $json.callback_query;
const data = cq.data || '';
const [action, draftId] = data.split(':');

const wfData = $getWorkflowStaticData('global');
const queue = wfData.pendingQueue || [];
const draft = queue.find(d => d.id === draftId);

return {
  json: {
    action: action,
    draft_id: draftId,
    callback_query_id: cq.id,
    chat_id: cq.message.chat.id,
    message_id: cq.message.message_id,
    draft: draft || null,
    draft_found: !!draft
  }
};

