const conflict = queue.find(d => d.status === 'awaiting_edit' && d.id !== draftId);
if (conflict) {
  return { json: { blocked: true, blocking_phone: conflict.customer_phone || 'unknown', draft_id: draftId } };
}
if (entry) entry.status = 'awaiting_edit';
return { json: {
  blocked: false,
  draft_id: draftId,
  customer_phone: entry ? entry.customer_phone : 'unknown',
  original_draft: entry ? entry.draft_text : 'unknown'
} };

