// R1: build a failure alert for Zayn from a node error-output item
const j = $input.item.json || {};
const err = j.error || {};
let msg;
try { msg = err.message || err.description || (typeof err === 'string' ? err : '') || JSON.stringify(err); }
catch (e) { msg = 'unrecognised error'; }
let phone = j.customerPhone || j.customer_phone || '';
try { if (!phone && j.draft) phone = j.draft.customer_phone || ''; } catch (e) {}
const text = '\u26a0\ufe0f Phase 1B \u2014 a step failed\n\n'
  + 'The workflow caught the error instead of dying silently.\n\n'
  + 'Error: ' + (msg || 'unknown') + '\n'
  + (phone ? 'Customer: ' + phone + '\n' : '')
  + '\nNothing was force-sent. Open N8N \u2192 Executions to find the failed '
  + 'node and check the pending queue, then handle it manually.';
return { json: { chat_id: 5532831477, alert_text: text } };

